server.ps1.content:
# Lightweight Static Web Server for NutriSync AI
param(
  [int]$Port = 8000,
  [string]$Path = "C:\Users\HARSHXO\OneDrive\Desktop\nutrition agent"
)

$listener = New-Object System.Net.HttpListener
$prefix = "http://localhost:$Port/"
$listener.Prefixes.Add($prefix)

try {
  $listener.Start()
  Write-Host "=========================================================="
  Write-Host "🚀 NutriSync AI Server is LIVE at: $prefix"
  Write-Host "   Open in browser: $prefix"
  Write-Host "   Serving directory: $Path"
  Write-Host "=========================================================="
} catch {
  Write-Host "Port $Port busy, trying 8080..."
  $Port = 8080
  $listener = New-Object System.Net.HttpListener
  $prefix = "http://localhost:$Port/"
  $listener.Prefixes.Add($prefix)
  $listener.Start()
  Write-Host "🚀 NutriSync AI Server is LIVE at: $prefix"
}

$mimeTypes = @{
  ".html" = "text/html; charset=utf-8"
  ".css"  = "text/css; charset=utf-8"
  ".js"   = "application/javascript; charset=utf-8"
  ".svg"  = "image/svg+xml"
  ".png"  = "image/png"
  ".jpg"  = "image/jpeg"
  ".pdf"  = "application/pdf"
  ".json" = "application/json"
  ".md"   = "text/plain; charset=utf-8"
}

while ($listener.IsListening) {
  try {
    $context = $listener.GetContext()
    $request = $context.Request
    $response = $context.Response

    $urlPath = $request.Url.LocalPath.TrimStart('/')
    if ([string]::IsNullOrEmpty($urlPath) -or $urlPath -eq "/") {
      $urlPath = "index.html"
    }

    $filePath = [System.IO.Path]::Combine($Path, $urlPath.Replace('/', '\'))

    if ([System.IO.File]::Exists($filePath)) {
      $ext = [System.IO.Path]::GetExtension($filePath).ToLower()
      $contentType = $mimeTypes[$ext]
      if (-not $contentType) { $contentType = "application/octet-stream" }

      $response.ContentType = $contentType
      $response.AddHeader("Access-Control-Allow-Origin", "*")
      $response.AddHeader("Cache-Control", "no-cache, no-store, must-revalidate")

      $bytes = [System.IO.File]::ReadAllBytes($filePath)
      $response.ContentLength64 = $bytes.Length
      $response.OutputStream.Write($bytes, 0, $bytes.Length)
    } else {
      $response.StatusCode = 404
      $msg = [System.Text.Encoding]::UTF8.GetBytes("404 Not Found: $urlPath")
      $response.OutputStream.Write($msg, 0, $msg.Length)
    }
    $response.OutputStream.Close()
  } catch {
    # Request processing error, continue loop
  }
}

css/styles.css.content:
/* ==========================================================================
   NutriMate AI - Design System & Stylesheet
   Palette: Primary Green (#2E9E6B), Deep Teal (#0F5C5C), Accent Amber (#F5A524)
   Responsive, Accessible (WCAG AA), Zero-dependency
   ========================================================================== */

:root {
  /* Color Tokens - Modern Royal Azure & Electric Blue Theme */
  --primary: #2563EB;          /* Royal Blue */
  --primary-hover: #1D4ED8;    /* Deep Royal Blue */
  --primary-light: #EFF6FF;    /* Ice Blue */
  --primary-border: #BFDBFE;   /* Soft Azure Border */

  --secondary: #0F172A;        /* Midnight Slate */
  --secondary-hover: #1E293B;
  --secondary-light: #F8FAFC;

  --accent: #F59E0B;           /* Energetic Amber Gold */
  --accent-hover: #D97706;
  --accent-light: #FEF3C7;

  --azure: #0284C7;            /* Sky / Azure */
  --azure-light: #F0F9FF;
  --indigo: #4F46E5;           /* Electric Indigo */

  --ibm-blue: #0F62FE;
  --ibm-blue-light: #EDF5FF;

  --bg-main: #F8FAFC;          /* Clean Cool Slate Canvas */
  --bg-surface: #FFFFFF;
  --bg-surface-elevated: #FFFFFF;
  --bg-subtle: #F1F5F9;

  --text-primary: #0F172A;
  --text-secondary: #475569;
  --text-muted: #64748B;
  --text-on-primary: #FFFFFF;

  --border-light: #E2E8F0;
  --border-subtle: #CBD5E1;

  --status-success: #10B981;
  --status-warning: #F59E0B;
  --status-danger: #EF4444;
  --status-info: #2563EB;

  /* Typography */
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
  --font-heading: 'Poppins', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;

  /* Spacing & Radii */
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 18px;
  --radius-full: 9999px;

  --shadow-sm: 0 1px 3px rgba(15, 23, 42, 0.05);
  --shadow-md: 0 4px 14px rgba(37, 99, 235, 0.08);
  --shadow-lg: 0 12px 30px rgba(37, 99, 235, 0.12);

  --transition-fast: 150ms ease;
  --transition-normal: 250ms ease;
}

/* Dark Mode Variables - Deep Cyber Midnight Navy */
[data-theme="dark"] {
  --bg-main: #0A0F1D;          /* Cyber Midnight Navy */
  --bg-surface: #111A2E;       /* Deep Navy Glass */
  --bg-surface-elevated: #18233C;
  --bg-subtle: #152037;

  --text-primary: #F8FAFC;
  --text-secondary: #94A3B8;
  --text-muted: #64748B;

  --border-light: #1E2D4A;
  --border-subtle: #2B3D63;

  --primary: #38BDF8;          /* Electric Azure in Dark */
  --primary-hover: #60A5FA;
  --primary-light: #1E293B;
  --primary-border: #2563EB;

  --secondary: #F1F5F9;
  --secondary-hover: #FFFFFF;
  --secondary-light: #1E293B;

  --accent: #F59E0B;
  --accent-light: #451A03;
  --ibm-blue-light: #1E293B;
}

/* Reset & Box Sizing */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-family: var(--font-sans);
  font-size: 16px;
  line-height: 1.6;
  color: var(--text-primary);
  background-color: var(--bg-main);
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
}

body {
  overflow-x: hidden;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

img, svg {
  max-width: 100%;
  display: block;
}

a {
  color: var(--primary);
  text-decoration: none;
  transition: color var(--transition-fast);
}

a:hover {
  color: var(--primary-hover);
}

button, input, select, textarea {
  font-family: inherit;
  font-size: inherit;
  color: inherit;
}

button {
  cursor: pointer;
  border: none;
  background: none;
}

/* Container */
.container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 1.5rem;
}

/* Skip Link for Accessibility */
.skip-link {
  position: absolute;
  top: -40px;
  left: 1rem;
  background: var(--primary);
  color: #fff;
  padding: 0.5rem 1rem;
  z-index: 1000;
  border-radius: var(--radius-sm);
  transition: top var(--transition-fast);
  font-weight: 600;
}

.skip-link:focus {
  top: 1rem;
}

/* ==========================================================================
   Header & Navigation
   ========================================================================== */
.site-header {
  position: sticky;
  top: 0;
  z-index: 900;
  background: rgba(255, 255, 255, 0.92);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border-light);
  transition: background var(--transition-normal);
}

[data-theme="dark"] .site-header {
  background: rgba(21, 34, 30, 0.92);
}

.nav-wrap {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 4.5rem;
}

.logo-link {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.logo-img {
  height: 42px;
  width: auto;
}

.nav-menu {
  display: flex;
  align-items: center;
  gap: 1.5rem;
  list-style: none;
}

.nav-link {
  font-weight: 500;
  color: var(--text-secondary);
  font-size: 0.95rem;
  padding: 0.35rem 0.2rem;
  position: relative;
}

.nav-link:hover,
.nav-link:focus-visible {
  color: var(--primary);
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.theme-toggle-btn {
  width: 40px;
  height: 40px;
  border-radius: var(--radius-full);
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg-subtle);
  color: var(--text-secondary);
  border: 1px solid var(--border-light);
  transition: all var(--transition-fast);
}

.theme-toggle-btn:hover {
  color: var(--primary);
  border-color: var(--primary);
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  font-weight: 600;
  font-size: 0.95rem;
  padding: 0.65rem 1.25rem;
  border-radius: var(--radius-full);
  transition: all var(--transition-normal);
  text-decoration: none;
}

.btn-primary {
  background: linear-gradient(135deg, #2563EB 0%, #0284C7 100%);
  color: #fff;
  border: 1px solid rgba(255, 255, 255, 0.2);
  box-shadow: 0 4px 14px rgba(37, 99, 235, 0.32);
}

.btn-primary:hover {
  background: linear-gradient(135deg, #1D4ED8 0%, #0369A1 100%);
  color: #fff;
  transform: translateY(-2px);
  box-shadow: 0 8px 22px rgba(37, 99, 235, 0.45);
}

.btn-outline {
  border: 1.5px solid var(--primary);
  color: var(--primary);
  background: transparent;
}

.btn-outline:hover {
  background: var(--primary-light);
  color: var(--primary);
}

.btn-secondary {
  background: var(--secondary);
  color: #fff;
}

.btn-secondary:hover {
  background: var(--secondary-hover);
  color: #fff;
}

.mobile-toggle-btn {
  display: none;
  width: 40px;
  height: 40px;
  border-radius: var(--radius-sm);
  background: var(--bg-subtle);
  border: 1px solid var(--border-light);
}

/* ==========================================================================
   Hero Section
   ========================================================================== */
.hero-section {
  padding: 4.5rem 0 3.5rem;
  background: radial-gradient(circle at 85% 15%, rgba(37, 99, 235, 0.12) 0%, transparent 60%),
              radial-gradient(circle at 15% 85%, rgba(2, 132, 199, 0.09) 0%, transparent 55%);
  position: relative;
}

.hero-grid {
  display: grid;
  grid-template-columns: 1.15fr 0.85fr;
  align-items: center;
  gap: 3rem;
}

.badge-pill {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  background: var(--ibm-blue-light);
  color: var(--ibm-blue);
  border: 1px solid rgba(15, 98, 254, 0.2);
  padding: 0.35rem 0.85rem;
  border-radius: var(--radius-full);
  font-size: 0.85rem;
  font-weight: 600;
  margin-bottom: 1.25rem;
}

.badge-pill svg {
  width: 16px;
  height: 16px;
}

.hero-title {
  font-family: var(--font-heading);
  font-size: 2.85rem;
  font-weight: 800;
  line-height: 1.15;
  color: var(--text-primary);
  margin-bottom: 1.25rem;
  letter-spacing: -0.02em;
}

.hero-title .highlight {
  color: var(--primary);
  position: relative;
  display: inline-block;
}

.hero-subtitle {
  font-size: 1.15rem;
  color: var(--text-secondary);
  line-height: 1.65;
  margin-bottom: 2rem;
  max-width: 580px;
}

.hero-cta-group {
  display: flex;
  align-items: center;
  gap: 1rem;
  flex-wrap: wrap;
  margin-bottom: 2rem;
}

.hero-trust-row {
  display: flex;
  align-items: center;
  gap: 1.5rem;
  padding-top: 1.25rem;
  border-top: 1px solid var(--border-light);
  font-size: 0.88rem;
  color: var(--text-muted);
}

.trust-item {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  font-weight: 500;
}

.trust-item svg {
  color: var(--primary);
  width: 18px;
  height: 18px;
}

/* Hero Visual Card */
.hero-card-preview {
  background: var(--bg-surface);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-lg);
  padding: 1.75rem;
  box-shadow: var(--shadow-lg);
  position: relative;
}

.preview-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 1rem;
  border-bottom: 1px solid var(--border-light);
  margin-bottom: 1.25rem;
}

.preview-agent-info {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.agent-avatar {
  width: 42px;
  height: 42px;
  border-radius: var(--radius-full);
  background: linear-gradient(135deg, #2563EB, #0284C7);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-weight: 700;
  box-shadow: 0 4px 12px rgba(37, 99, 235, 0.3);
}

.agent-status-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  font-size: 0.8rem;
  color: var(--status-success);
  font-weight: 600;
}

.status-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--status-success);
}

.chat-bubble-mock {
  background: var(--bg-subtle);
  border-radius: var(--radius-md);
  padding: 1rem;
  font-size: 0.92rem;
  line-height: 1.5;
  color: var(--text-primary);
  margin-bottom: 0.75rem;
}

.chat-bubble-mock.agent {
  border-left: 3px solid var(--primary);
}

.chat-bubble-mock.user {
  background: var(--primary-light);
  border-right: 3px solid var(--primary);
  color: var(--text-primary);
  text-align: right;
}

/* ==========================================================================
   Problem vs Solution Strip
   ========================================================================== */
.section {
  padding: 4.5rem 0;
}

.section-alt {
  background: var(--bg-subtle);
}

.section-head {
  text-align: center;
  max-width: 680px;
  margin: 0 auto 3rem;
}

.section-eyebrow {
  font-size: 0.85rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--primary);
  margin-bottom: 0.5rem;
}

.section-title {
  font-family: var(--font-heading);
  font-size: 2.15rem;
  font-weight: 700;
  color: var(--text-primary);
  letter-spacing: -0.01em;
  margin-bottom: 0.85rem;
}

.section-desc {
  font-size: 1.05rem;
  color: var(--text-secondary);
}

.compare-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
}

.compare-card {
  background: var(--bg-surface);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-md);
  padding: 1.75rem;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  transition: transform var(--transition-normal), box-shadow var(--transition-normal);
}

.compare-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
}

.compare-card .gap-tag {
  display: inline-block;
  background: #FEE2E2;
  color: #B91C1C;
  font-size: 0.75rem;
  font-weight: 700;
  padding: 0.2rem 0.6rem;
  border-radius: var(--radius-full);
  margin-bottom: 0.75rem;
  align-self: flex-start;
}

.compare-card .solution-tag {
  display: inline-block;
  background: var(--primary-light);
  color: var(--primary);
  font-size: 0.75rem;
  font-weight: 700;
  padding: 0.2rem 0.6rem;
  border-radius: var(--radius-full);
  margin-top: 1rem;
  margin-bottom: 0.5rem;
  align-self: flex-start;
}

.compare-card h3 {
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--text-primary);
  margin-bottom: 0.5rem;
}

.compare-card p {
  font-size: 0.92rem;
  color: var(--text-secondary);
  line-height: 1.55;
}

/* ==========================================================================
   How It Works (4 Steps)
   ========================================================================== */
.steps-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1.5rem;
  position: relative;
}

.step-card {
  background: var(--bg-surface);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-md);
  padding: 1.75rem;
  position: relative;
  display: flex;
  flex-direction: column;
}

.step-num {
  width: 36px;
  height: 36px;
  border-radius: var(--radius-full);
  background: var(--primary);
  color: #fff;
  font-weight: 800;
  font-size: 1rem;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.25rem;
}

.step-card h4 {
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--text-primary);
  margin-bottom: 0.6rem;
}

.step-card p {
  font-size: 0.9rem;
  color: var(--text-secondary);
  line-height: 1.55;
}

/* ==========================================================================
   Features Grid
   ========================================================================== */
.features-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
}

.feature-card {
  background: var(--bg-surface);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-md);
  padding: 1.75rem;
  transition: transform var(--transition-normal), box-shadow var(--transition-normal);
}

.feature-card:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-md);
}

.feature-icon-box {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-sm);
  background: var(--primary-light);
  color: var(--primary);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.25rem;
}

.feature-icon-box svg {
  width: 24px;
  height: 24px;
}

.feature-card h3 {
  font-size: 1.15rem;
  font-weight: 700;
  margin-bottom: 0.5rem;
  color: var(--text-primary);
}

.feature-card p {
  font-size: 0.92rem;
  color: var(--text-secondary);
  line-height: 1.55;
}

/* ==========================================================================
   Health Calculators & Dashboard Section
   ========================================================================== */
.calc-dashboard {
  display: grid;
  grid-template-columns: 1.1fr 0.9fr;
  gap: 2rem;
  align-items: start;
}

.calc-form-card, .calc-results-card {
  background: var(--bg-surface);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-lg);
  padding: 2rem;
  box-shadow: var(--shadow-sm);
}

.calc-card-header {
  margin-bottom: 1.5rem;
  padding-bottom: 1rem;
  border-bottom: 1px solid var(--border-light);
}

.calc-card-header h3 {
  font-size: 1.35rem;
  font-weight: 700;
  color: var(--text-primary);
}

.calc-card-header p {
  font-size: 0.88rem;
  color: var(--text-muted);
}

.form-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1.25rem;
}

.form-group {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

.form-group.full-width {
  grid-column: span 2;
}

.form-label {
  font-size: 0.88rem;
  font-weight: 600;
  color: var(--text-primary);
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.form-input, .form-select {
  width: 100%;
  padding: 0.7rem 0.9rem;
  background: var(--bg-subtle);
  border: 1.5px solid var(--border-light);
  border-radius: var(--radius-sm);
  color: var(--text-primary);
  font-size: 0.95rem;
  transition: border-color var(--transition-fast), background var(--transition-fast);
}

.form-input:focus, .form-select:focus {
  outline: none;
  border-color: var(--primary);
  background: var(--bg-surface);
}

.input-with-toggle {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

.unit-toggle-wrap {
  display: inline-flex;
  background: var(--bg-subtle);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-full);
  padding: 2px;
  align-self: flex-start;
  margin-bottom: 0.25rem;
}

.unit-toggle-btn {
  font-size: 0.75rem;
  font-weight: 700;
  padding: 0.2rem 0.65rem;
  border-radius: var(--radius-full);
  color: var(--text-secondary);
}

.unit-toggle-btn.active {
  background: var(--primary);
  color: #fff;
}

.height-ft-in-inputs {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.5rem;
}

.field-error {
  font-size: 0.78rem;
  color: var(--status-danger);
  display: none;
  font-weight: 500;
}

.field-error.visible {
  display: block;
}

/* Radio Pill Group */
.radio-pill-group {
  display: flex;
  gap: 0.5rem;
}

.radio-pill-label {
  flex: 1;
  text-align: center;
  padding: 0.6rem 0.8rem;
  background: var(--bg-subtle);
  border: 1.5px solid var(--border-light);
  border-radius: var(--radius-sm);
  font-size: 0.9rem;
  font-weight: 600;
  cursor: pointer;
  transition: all var(--transition-fast);
}

.radio-pill-label input[type="radio"] {
  display: none;
}

.radio-pill-label:has(input[type="radio"]:checked) {
  background: var(--primary-light);
  border-color: var(--primary);
  color: var(--primary);
}

/* Results Display */
.metric-summary-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem;
  margin-bottom: 1.5rem;
}

.metric-box {
  background: var(--bg-subtle);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-md);
  padding: 1.25rem;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.metric-label {
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 0.35rem;
}

.metric-val {
  font-size: 1.85rem;
  font-weight: 800;
  color: var(--text-primary);
  line-height: 1.1;
}

.metric-sub {
  font-size: 0.8rem;
  font-weight: 600;
  margin-top: 0.35rem;
}

.badge-tag {
  display: inline-block;
  padding: 0.2rem 0.5rem;
  border-radius: var(--radius-full);
  font-size: 0.75rem;
  font-weight: 700;
  margin-top: 0.25rem;
}

/* Calorie Target Banner */
.calorie-target-card {
  background: linear-gradient(135deg, rgba(37, 99, 235, 0.08) 0%, rgba(2, 132, 199, 0.06) 100%);
  border: 1.5px solid var(--primary-border);
  border-radius: var(--radius-md);
  padding: 1.5rem;
  text-align: center;
  margin-bottom: 1.5rem;
}

.calorie-target-title {
  font-size: 0.88rem;
  font-weight: 700;
  text-transform: uppercase;
  color: var(--secondary);
  letter-spacing: 0.05em;
  margin-bottom: 0.3rem;
}

.calorie-target-num {
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--text-primary);
  line-height: 1;
}

.calorie-target-unit {
  font-size: 1rem;
  font-weight: 600;
  color: var(--text-secondary);
}

.safety-floor-alert {
  margin-top: 0.75rem;
  padding: 0.6rem 0.85rem;
  background: #FFFBEB;
  border: 1px solid #FCD34D;
  border-radius: var(--radius-sm);
  color: #92400E;
  font-size: 0.82rem;
  font-weight: 500;
  text-align: left;
}

.minor-advisory-box {
  padding: 1.25rem;
  background: #EFF6FF;
  border: 1.5px solid #93C5FD;
  border-radius: var(--radius-md);
  color: #1E40AF;
  font-size: 0.92rem;
  line-height: 1.5;
  margin-bottom: 1.5rem;
}

/* Macro Breakdown Bars */
.macro-section {
  margin-bottom: 1.5rem;
}

.macro-title {
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--text-primary);
  margin-bottom: 0.75rem;
}

.macro-stacked-bar {
  display: flex;
  height: 14px;
  border-radius: var(--radius-full);
  overflow: hidden;
  background: var(--bg-subtle);
  margin-bottom: 1rem;
}

.macro-bar-seg {
  height: 100%;
  transition: width var(--transition-normal);
}

.macro-bar-seg.protein { background: #3B82F6; }
.macro-bar-seg.carbs { background: #10B981; }
.macro-bar-seg.fats { background: #F59E0B; }

.macro-legend-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0.75rem;
}

.macro-item {
  background: var(--bg-subtle);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  padding: 0.75rem;
}

.macro-item-label {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--text-secondary);
}

.dot-indicator {
  width: 8px;
  height: 8px;
  border-radius: 50%;
}

.dot-protein { background: #3B82F6; }
.dot-carbs { background: #10B981; }
.dot-fats { background: #F59E0B; }

.macro-item-value {
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--text-primary);
  margin-top: 0.25rem;
}

.macro-item-pct {
  font-size: 0.75rem;
  color: var(--text-muted);
}

/* Sync to Agent CTA */
.send-profile-btn {
  width: 100%;
  padding: 0.95rem 1.4rem;
  border-radius: var(--radius-md);
  font-size: 1rem;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.6rem;
  background: linear-gradient(135deg, #2563EB 0%, #0284C7 100%);
  color: #fff;
  border: 1px solid rgba(255, 255, 255, 0.2);
  box-shadow: 0 4px 18px rgba(37, 99, 235, 0.32);
  transition: all var(--transition-normal);
}

.send-profile-btn:hover {
  background: linear-gradient(135deg, #1D4ED8 0%, #0369A1 100%);
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(37, 99, 235, 0.45);
}

.calc-disclaimer-text {
  font-size: 0.78rem;
  color: var(--text-muted);
  text-align: center;
  margin-top: 0.75rem;
}

/* ==========================================================================
   Sample Meal Plans Section
   ========================================================================== */
.plans-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.75rem;
}

.plan-card {
  background: var(--bg-surface);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-lg);
  padding: 1.75rem;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
}

.plan-header {
  padding-bottom: 1rem;
  border-bottom: 1px solid var(--border-light);
  margin-bottom: 1.25rem;
}

.plan-tag {
  display: inline-block;
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  padding: 0.2rem 0.6rem;
  border-radius: var(--radius-full);
  margin-bottom: 0.5rem;
}

.plan-tag.gain { background: #DBEAFE; color: #1E40AF; }
.plan-tag.diabetes { background: #FEF3C7; color: #92400E; }
.plan-tag.budget { background: #DCFCE7; color: #166534; }

.plan-title {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--text-primary);
  margin-bottom: 0.35rem;
}

.plan-metrics-row {
  display: flex;
  gap: 1rem;
  font-size: 0.82rem;
  color: var(--text-muted);
  font-weight: 500;
}

.plan-meals-list {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  margin-bottom: 1.5rem;
  flex: 1;
}

.meal-slot {
  background: var(--bg-subtle);
  border-radius: var(--radius-sm);
  padding: 0.85rem;
  font-size: 0.88rem;
}

.meal-time {
  font-weight: 700;
  color: var(--primary);
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 0.25rem;
}

.meal-desc {
  color: var(--text-primary);
  font-weight: 500;
  margin-bottom: 0.25rem;
}

.meal-alt {
  font-size: 0.78rem;
  color: var(--text-muted);
  font-style: italic;
}

.plan-why-box {
  background: var(--primary-light);
  border-left: 3px solid var(--primary);
  padding: 0.75rem;
  border-radius: 0 var(--radius-sm) var(--radius-sm) 0;
  font-size: 0.82rem;
  color: var(--text-secondary);
  line-height: 1.45;
  margin-bottom: 1rem;
}

.plan-why-box strong {
  color: var(--primary);
}

.plan-disclaimer {
  font-size: 0.75rem;
  color: var(--text-muted);
  font-style: italic;
  text-align: center;
}

/* ==========================================================================
   watsonx Chat Integration Section
   ========================================================================== */
.chat-section-wrap {
  background: var(--bg-surface);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-lg);
  padding: 2.5rem;
  box-shadow: var(--shadow-md);
}

.chat-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2.5rem;
  align-items: center;
}

.prompt-chips-title {
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--text-primary);
  margin-bottom: 0.75rem;
}

.chips-list {
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
  margin-bottom: 1.5rem;
}

.prompt-chip {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.75rem 1rem;
  background: var(--bg-subtle);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-md);
  font-size: 0.88rem;
  color: var(--text-primary);
  font-weight: 500;
  text-align: left;
  transition: all var(--transition-fast);
}

.prompt-chip:hover {
  background: var(--primary-light);
  border-color: var(--primary);
  color: var(--primary);
  transform: translateX(4px);
}

.prompt-chip .copy-icon {
  width: 16px;
  height: 16px;
  color: var(--text-muted);
}

/* Chat Embed / Fallback Box */
.chat-embed-box {
  background: var(--bg-subtle);
  border: 2px dashed var(--border-subtle);
  border-radius: var(--radius-lg);
  padding: 2rem;
  text-align: center;
  position: relative;
  min-height: 380px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}

.chat-fallback-icon {
  width: 60px;
  height: 60px;
  border-radius: var(--radius-full);
  background: var(--primary-light);
  color: var(--primary);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.25rem;
}

.chat-embed-box h4 {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--text-primary);
  margin-bottom: 0.5rem;
}

.chat-embed-box p {
  font-size: 0.9rem;
  color: var(--text-secondary);
  max-width: 380px;
  margin-bottom: 1.5rem;
  line-height: 1.5;
}

.chat-embed-box .code-snippet-note {
  font-size: 0.78rem;
  background: rgba(0,0,0,0.04);
  padding: 0.4rem 0.8rem;
  border-radius: var(--radius-sm);
  color: var(--text-muted);
  font-family: monospace;
}

/* ==========================================================================
   Architecture Section
   ========================================================================== */
.arch-card {
  background: var(--bg-surface);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-lg);
  padding: 2rem;
  box-shadow: var(--shadow-sm);
}

.arch-visual-wrap {
  width: 100%;
  border-radius: var(--radius-md);
  overflow: hidden;
  border: 1px solid var(--border-light);
  margin-bottom: 2rem;
  background: #FFFFFF;
}

.arch-legend-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1.25rem;
}

.arch-legend-item {
  background: var(--bg-subtle);
  border-radius: var(--radius-sm);
  padding: 1rem;
}

.arch-legend-item h4 {
  font-size: 0.92rem;
  font-weight: 700;
  color: var(--text-primary);
  margin-bottom: 0.35rem;
}

.arch-legend-item p {
  font-size: 0.82rem;
  color: var(--text-secondary);
  line-height: 1.45;
}

/* ==========================================================================
   Responsible AI Section
   ========================================================================== */
.responsible-table-wrap {
  background: var(--bg-surface);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
}

.responsible-table {
  width: 100%;
  border-collapse: collapse;
  text-align: left;
}

.responsible-table th {
  background: var(--bg-subtle);
  padding: 1.15rem 1.5rem;
  font-size: 0.92rem;
  font-weight: 700;
  color: var(--text-primary);
  border-bottom: 1px solid var(--border-light);
}

.responsible-table td {
  padding: 1.15rem 1.5rem;
  font-size: 0.9rem;
  color: var(--text-secondary);
  border-bottom: 1px solid var(--border-light);
  line-height: 1.5;
}

.responsible-table tr:last-child td {
  border-bottom: none;
}

.responsible-table .principle-name {
  font-weight: 700;
  color: var(--text-primary);
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

/* ==========================================================================
   Site Footer
   ========================================================================== */
.site-footer {
  background: #090E1A;
  color: #94A3B8;
  padding: 4rem 0 2rem;
  margin-top: auto;
  border-top: 1px solid #1E293B;
}

.footer-grid {
  display: grid;
  grid-template-columns: 1.5fr 1fr 1fr;
  gap: 3rem;
  padding-bottom: 3rem;
  border-bottom: 1px solid #1E293B;
}

.footer-brand h4 {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 800;
  color: #FFFFFF;
  margin-bottom: 0.75rem;
}

.footer-brand p {
  font-size: 0.92rem;
  line-height: 1.6;
  max-width: 380px;
  color: #94A3B8;
}

.footer-col h5 {
  font-size: 1rem;
  font-weight: 700;
  color: #FFFFFF;
  margin-bottom: 1rem;
}

.footer-links {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
}

.footer-links a {
  color: #94A3B8;
  font-size: 0.9rem;
  transition: color var(--transition-fast);
}

.footer-links a:hover {
  color: #38BDF8;
}

/* Mandatory Medical Disclaimer Banner in Footer */
.footer-disclaimer-banner {
  background: #0F172A;
  border: 1px solid #1E293B;
  border-radius: var(--radius-md);
  padding: 1.25rem 1.5rem;
  margin: 2rem 0;
  display: flex;
  align-items: flex-start;
  gap: 1rem;
}

.disclaimer-icon {
  width: 24px;
  height: 24px;
  color: #F59E0B;
  flex-shrink: 0;
  margin-top: 2px;
}

.disclaimer-text {
  font-size: 0.85rem;
  line-height: 1.5;
  color: #CBD5E1;
}

.disclaimer-text strong {
  color: #FFFFFF;
}

.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 0.82rem;
  color: #64748B;
  padding-top: 1.5rem;
}

/* ==========================================================================
   Toast Notification
   ========================================================================== */
.toast-notice {
  position: fixed;
  bottom: 2rem;
  right: 2rem;
  background: var(--text-primary);
  color: #FFFFFF;
  padding: 0.85rem 1.4rem;
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-lg);
  font-size: 0.9rem;
  font-weight: 600;
  display: flex;
  align-items: center;
  gap: 0.6rem;
  z-index: 2000;
  opacity: 0;
  transform: translateY(16px);
  pointer-events: none;
  transition: opacity var(--transition-normal), transform var(--transition-normal);
}

.toast-notice.visible {
  opacity: 1;
  transform: translateY(0);
}

.toast-notice svg {
  color: var(--status-success);
  width: 18px;
  height: 18px;
}

/* ==========================================================================
   Responsive Breakpoints
   ========================================================================== */
@media (max-width: 1024px) {
  .hero-grid {
    grid-template-columns: 1fr;
    gap: 2.5rem;
  }
  .compare-grid, .steps-grid, .features-grid, .plans-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .calc-dashboard, .chat-grid {
    grid-template-columns: 1fr;
  }
  .arch-legend-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .footer-grid {
    grid-template-columns: 1fr 1fr;
  }
}

@media (max-width: 768px) {
  .nav-menu {
    display: none;
  }
  .mobile-toggle-btn {
    display: flex;
    align-items: center;
    justify-content: center;
  }
  .nav-menu.mobile-open {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: 100%;
    left: 0;
    right: 0;
    background: var(--bg-surface);
    border-bottom: 1px solid var(--border-light);
    padding: 1.5rem;
    box-shadow: var(--shadow-lg);
    gap: 1rem;
  }
  .hero-title {
    font-size: 2.2rem;
  }
  .compare-grid, .steps-grid, .features-grid, .plans-grid, .arch-legend-grid {
    grid-template-columns: 1fr;
  }
  .form-grid {
    grid-template-columns: 1fr;
  }
  .form-group.full-width {
    grid-column: span 1;
  }
  .metric-summary-grid {
    grid-template-columns: 1fr;
  }
  .footer-grid {
    grid-template-columns: 1fr;
    gap: 2rem;
  }
  .footer-bottom {
    flex-direction: column;
    gap: 0.5rem;
    text-align: center;
  }
}

@media (max-width: 480px) {
  .container {
    padding: 0 1rem;
  }
  .hero-title {
    font-size: 1.85rem;
  }
  .hero-cta-group {
    flex-direction: column;
    width: 100%;
  }
  .btn {
    width: 100%;
  }
  .calc-form-card, .calc-results-card, .chat-section-wrap {
    padding: 1.25rem;
  }
}


/* ==========================================================================
   Chat Live Card — Agent Active State
   ========================================================================== */

.chat-live-card {
  border: 1.5px solid var(--primary-border) !important;
  background: linear-gradient(145deg, var(--bg-surface) 0%, var(--primary-light) 100%) !important;
  box-shadow: 0 4px 24px rgba(37, 99, 235, 0.10) !important;
  position: relative;
  overflow: hidden;
}

[data-theme="dark"] .chat-live-card {
  background: linear-gradient(145deg, #0A0F1D 0%, #0f1e3d 100%) !important;
  border-color: #1e3a6e !important;
  box-shadow: 0 4px 32px rgba(56, 189, 248, 0.10) !important;
}

/* Pulsing LIVE badge */
.live-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  background: #dcfce7;
  color: #16a34a;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  padding: 0.3rem 0.75rem;
  border-radius: 999px;
  margin-bottom: 1rem;
  border: 1px solid #bbf7d0;
}

[data-theme="dark"] .live-badge {
  background: #052e16;
  color: #4ade80;
  border-color: #166534;
}

.live-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #22c55e;
  display: inline-block;
  animation: livePulse 1.4s ease-in-out infinite;
}

@keyframes livePulse {
  0%, 100% { opacity: 1; transform: scale(1); }
  50%       { opacity: 0.5; transform: scale(1.4); }
}

/* Arrow hint */
.chat-arrow-hint {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  width: 100%;
  margin: 0.5rem 0 0.75rem;
  opacity: 0.75;
  animation: arrowBounce 2s ease-in-out infinite;
}

@keyframes arrowBounce {
  0%, 100% { transform: translateY(0); }
  50%       { transform: translateY(5px); }
}

/* Quick steps list */
.live-steps {
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
  width: 100%;
  max-width: 300px;
  margin-top: 0.75rem;
}

.live-step {
  display: flex;
  align-items: flex-start;
  gap: 0.6rem;
  font-size: 0.84rem;
  color: var(--text-secondary);
}

.step-num {
  min-width: 22px;
  height: 22px;
  background: var(--primary);
  color: #fff;
  border-radius: 50%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 0.72rem;
  font-weight: 700;
  flex-shrink: 0;
}

/* Outline button variant */
.btn-outline {
  background: transparent;
  color: var(--primary);
  border: 1.5px solid var(--primary);
  box-shadow: none;
}
.btn-outline:hover {
  background: var(--primary-light);
  color: var(--primary-hover);
  border-color: var(--primary-hover);
}
[data-theme="dark"] .btn-outline {
  color: #93c5fd;
  border-color: #1d4ed8;
}
[data-theme="dark"] .btn-outline:hover {
  background: #0f1e3d;
  color: #60a5fa;
}

/* Chat launch hint pill */
.chat-launch-hint {
  display: flex;
  align-items: center;
  gap: 0.65rem;
  margin-top: 1rem;
  padding: 0.65rem 1.1rem;
  background: linear-gradient(135deg, #2563eb15, #38bdf815);
  border: 1.5px dashed var(--primary);
  border-radius: 999px;
  font-size: 0.85rem;
  color: var(--text-secondary);
  animation: hintPulse 2.5s ease-in-out infinite;
}

[data-theme="dark"] .chat-launch-hint {
  background: linear-gradient(135deg, #1d4ed820, #0ea5e920);
  border-color: #38bdf8;
  color: #94a3b8;
}

.chat-launch-hint strong {
  color: var(--primary);
}

[data-theme="dark"] .chat-launch-hint strong {
  color: #38bdf8;
}

.chat-bubble-icon {
  width: 32px;
  height: 32px;
  background: var(--primary);
  color: #fff;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  box-shadow: 0 2px 8px rgba(37,99,235,0.35);
  animation: iconBounce 2s ease-in-out infinite;
}

[data-theme="dark"] .chat-bubble-icon {
  background: #0ea5e9;
  box-shadow: 0 2px 8px rgba(14,165,233,0.4);
}

@keyframes hintPulse {
  0%, 100% { box-shadow: 0 0 0 0 rgba(37,99,235,0.15); }
  50%       { box-shadow: 0 0 0 6px rgba(37,99,235,0); }
}

@keyframes iconBounce {
  0%, 100% { transform: scale(1); }
  50%       { transform: scale(1.12); }
}

