/**
 * NutriSync AI - Nutrition Calculators Engine
 * Pure mathematical functions for client-side nutritional calculations.
 * Compliance: Mifflin-St Jeor equation, WHO BMI standards, PRD Section 5.3.
 */

const ACTIVITY_FACTORS = {
  sedentary: 1.2,       // Little or no exercise, desk job
  light: 1.375,         // Light exercise 1-3 days/week
  moderate: 1.55,       // Moderate exercise 3-5 days/week
  active: 1.725,        // Hard exercise 6-7 days/week
  very_active: 1.9      // Very hard exercise, physical job or training 2x/day
};

const CALORIE_FLOORS = {
  male: 1500,
  female: 1200
};

/**
 * Validate user input ranges
 * @param {Object} inputs 
 * @returns {Object} { isValid: boolean, errors: Object }
 */
function validateInputs({ age, weight, height, sex, activity, goal }) {
  const errors = {};

  const numAge = Number(age);
  const numWeight = Number(weight);
  const numHeight = Number(height);

  if (isNaN(numAge) || numAge < 10 || numAge > 100) {
    errors.age = 'Please enter a valid age between 10 and 100.';
  }

  if (isNaN(numWeight) || numWeight < 20 || numWeight > 250) {
    errors.weight = 'Please enter a valid weight between 20 kg and 250 kg.';
  }

  if (isNaN(numHeight) || numHeight < 100 || numHeight > 250) {
    errors.height = 'Please enter a valid height between 100 cm and 250 cm.';
  }

  if (!['male', 'female'].includes(sex)) {
    errors.sex = 'Please select biological sex (male/female) for metabolic calculations.';
  }

  if (!ACTIVITY_FACTORS[activity]) {
    errors.activity = 'Please select an activity level.';
  }

  if (!['loss', 'maintain', 'gain'].includes(goal)) {
    errors.goal = 'Please select your primary nutrition goal.';
  }

  return {
    isValid: Object.keys(errors).length === 0,
    errors
  };
}

/**
 * Convert feet & inches to centimeters
 * @param {number} feet 
 * @param {number} inches 
 * @returns {number} cm rounded to 1 decimal
 */
function ftInToCm(feet, inches = 0) {
  const totalInches = (Number(feet) * 12) + Number(inches);
  return Math.round(totalInches * 2.54 * 10) / 10;
}

/**
 * Convert centimeters to feet & inches
 * @param {number} cm 
 * @returns {Object} { feet: number, inches: number }
 */
function cmToFtIn(cm) {
  const totalInches = Number(cm) / 2.54;
  const feet = Math.floor(totalInches / 12);
  const inches = Math.round(totalInches % 12);
  return { feet, inches };
}

/**
 * Calculate Body Mass Index (BMI) and categorization
 * @param {number} weightKg 
 * @param {number} heightCm 
 * @returns {Object} { bmi: number, category: string, color: string }
 */
function calculateBMI(weightKg, heightCm) {
  const heightM = heightCm / 100;
  const bmiRaw = weightKg / (heightM * heightM);
  const bmi = Math.round(bmiRaw * 10) / 10;

  let category = '';
  let color = '';

  if (bmi < 18.5) {
    category = 'Underweight';
    color = '#3B82F6'; // Blue
  } else if (bmi <= 24.9) {
    category = 'Normal weight';
    color = '#10B981'; // Green
  } else if (bmi <= 29.9) {
    category = 'Overweight';
    color = '#F59E0B'; // Amber
  } else {
    category = 'Obese';
    color = '#EF4444'; // Red
  }

  return {
    bmi,
    category,
    color,
    note: 'Categories are based on WHO guidelines and are indicative estimates only.'
  };
}

/**
 * Calculate Basal Metabolic Rate (BMR) using Mifflin-St Jeor formula
 * Male: 10·w + 6.25·h − 5·age + 5
 * Female: 10·w + 6.25·h − 5·age − 161
 * @param {number} weightKg 
 * @param {number} heightCm 
 * @param {number} age 
 * @param {string} sex ('male' | 'female')
 * @returns {number} BMR in kcal (rounded to 1 decimal)
 */
function calculateBMR(weightKg, heightCm, age, sex) {
  const base = (10 * weightKg) + (6.25 * heightCm) - (5 * age);
  const bmr = sex === 'male' ? base + 5 : base - 161;
  return Math.round(bmr * 10) / 10;
}

/**
 * Calculate Total Daily Energy Expenditure (TDEE)
 * @param {number} bmr 
 * @param {string} activity 
 * @returns {number} TDEE in kcal (rounded to 1 decimal)
 */
function calculateTDEE(bmr, activity) {
  const factor = ACTIVITY_FACTORS[activity] || 1.2;
  return Math.round(bmr * factor * 10) / 10;
}

/**
 * Calculate Goal Calories with safety floor guardrails
 * Gain: TDEE + 400
 * Loss: TDEE - 400
 * Maintain: TDEE
 * @param {number} tdee 
 * @param {string} goal ('loss' | 'maintain' | 'gain')
 * @param {string} sex ('male' | 'female')
 * @returns {Object} { goalCalories: number, floorApplied: boolean, floorMessage?: string }
 */
function calculateGoalCalories(tdee, goal, sex) {
  let target = tdee;
  if (goal === 'loss') {
    target = tdee - 400;
  } else if (goal === 'gain') {
    target = tdee + 400;
  }

  target = Math.round(target);

  const minFloor = CALORIE_FLOORS[sex] || 1200;
  let floorApplied = false;
  let floorMessage = null;

  if (target < minFloor) {
    target = minFloor;
    floorApplied = true;
    floorMessage = `For health and safety, minimum daily calories are capped at ${minFloor} kcal for ${sex}s. For personalized extreme deficit, please consult a registered dietitian.`;
  }

  return {
    goalCalories: target,
    floorApplied,
    floorMessage
  };
}

/**
 * Calculate Macronutrient breakdown (Protein, Fats, Carbs)
 * Protein: 1.2 g/kg (maintain), 1.6 g/kg (gain), 1.8 g/kg (loss)
 * Fats: ~25% of total calories (9 kcal/g)
 * Carbs: Remaining calories (4 kcal/g)
 * @param {number} goalCalories 
 * @param {number} weightKg 
 * @param {string} goal 
 * @returns {Object} Macros in grams and calories
 */
function calculateMacros(goalCalories, weightKg, goal) {
  let proteinFactor = 1.2;
  if (goal === 'gain') proteinFactor = 1.6;
  if (goal === 'loss') proteinFactor = 1.8;

  const proteinGrams = Math.round(weightKg * proteinFactor);
  const proteinKcal = Math.round(proteinGrams * 4);

  // 25% of calories from fat
  const fatKcal = Math.round(goalCalories * 0.25);
  const fatGrams = Math.round(fatKcal / 9);

  // Remaining calories to carbs
  let carbKcal = goalCalories - (proteinKcal + fatKcal);
  if (carbKcal < 0) carbKcal = 0;
  const carbGrams = Math.round(carbKcal / 4);

  const totalCalculatedKcal = proteinKcal + fatKcal + carbKcal;

  const proteinPct = Math.round((proteinKcal / totalCalculatedKcal) * 100);
  const fatPct = Math.round((fatKcal / totalCalculatedKcal) * 100);
  const carbPct = 100 - proteinPct - fatPct;

  return {
    protein: { grams: proteinGrams, kcal: proteinKcal, percentage: proteinPct },
    fat: { grams: fatGrams, kcal: fatKcal, percentage: fatPct },
    carbs: { grams: carbGrams, kcal: carbKcal, percentage: carbPct }
  };
}

/**
 * Master calculation coordinator
 * @param {Object} inputs { age, weight, height, sex, activity, goal }
 * @returns {Object} Complete nutritional assessment
 */
function assessNutrition(inputs) {
  const validation = validateInputs(inputs);
  if (!validation.isValid) {
    return { success: false, errors: validation.errors };
  }

  const age = Number(inputs.age);
  const weight = Number(inputs.weight);
  const height = Number(inputs.height);
  const { sex, activity, goal } = inputs;

  const bmiData = calculateBMI(weight, height);
  const bmr = calculateBMR(weight, height, age, sex);
  const tdee = calculateTDEE(bmr, activity);

  // Minor check (< 18 years)
  if (age < 18) {
    return {
      success: true,
      isMinor: true,
      minorMessage: 'For children and teenagers under 18, nutritional needs vary dynamically during growth. Please consult a qualified doctor or certified pediatric dietitian rather than using adult calorie targets.',
      bmiData,
      bmr,
      tdee,
      goalCalories: null,
      macros: null
    };
  }

  const { goalCalories, floorApplied, floorMessage } = calculateGoalCalories(tdee, goal, sex);
  const macros = calculateMacros(goalCalories, weight, goal);

  return {
    success: true,
    isMinor: false,
    inputs: { age, weight, height, sex, activity, goal },
    bmiData,
    bmr,
    tdee,
    goalCalories,
    floorApplied,
    floorMessage,
    macros
  };
}

// Export for Node/test environments or browser global
if (typeof module !== 'undefined' && module.exports) {
  module.exports = {
    validateInputs,
    ftInToCm,
    cmToFtIn,
    calculateBMI,
    calculateBMR,
    calculateTDEE,
    calculateGoalCalories,
    calculateMacros,
    assessNutrition,
    ACTIVITY_FACTORS,
    CALORIE_FLOORS
  };
}

