/**
 * NutriSync AI - UI Interactivity & Integration Logic
 * Handles interactive calculators, unit conversions, clipboard actions,
 * prompt chips, theme toggling, and Watsonx chat fallback detection.
 */

document.addEventListener('DOMContentLoaded', () => {
  initTheme();
  initNavigation();
  initHeightUnitToggle();
  initCalculator();
  initPromptChips();
  initCopyProfile();
  initWebchatFallback();
});

/* ==========================================================================
   Theme Management (Light / Dark Mode)
   ========================================================================== */
function initTheme() {
  const themeToggleBtn = document.getElementById('themeToggleBtn');
  if (!themeToggleBtn) return;

  const savedTheme = localStorage.getItem('nutrisync_theme') || 'light';
  document.documentElement.setAttribute('data-theme', savedTheme);
  updateThemeIcon(savedTheme);

  themeToggleBtn.addEventListener('click', () => {
    const currentTheme = document.documentElement.getAttribute('data-theme') || 'light';
    const newTheme = currentTheme === 'light' ? 'dark' : 'light';
    document.documentElement.setAttribute('data-theme', newTheme);
    localStorage.setItem('nutrisync_theme', newTheme);
    updateThemeIcon(newTheme);
  });
}

function updateThemeIcon(theme) {
  const btn = document.getElementById('themeToggleBtn');
  if (!btn) return;
  if (theme === 'dark') {
    btn.innerHTML = `<svg width="20" height="20" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z" /></svg>`;
    btn.setAttribute('aria-label', 'Switch to light mode');
  } else {
    btn.innerHTML = `<svg width="20" height="20" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z" /></svg>`;
    btn.setAttribute('aria-label', 'Switch to dark mode');
  }
}

/* ==========================================================================
   Mobile Navigation
   ========================================================================== */
function initNavigation() {
  const mobileToggle = document.getElementById('mobileNavToggle');
  const navMenu = document.getElementById('navMenu');

  if (mobileToggle && navMenu) {
    mobileToggle.addEventListener('click', () => {
      navMenu.classList.toggle('mobile-open');
    });

    navMenu.querySelectorAll('.nav-link').forEach(link => {
      link.addEventListener('click', () => {
        navMenu.classList.remove('mobile-open');
      });
    });
  }
}

/* ==========================================================================
   Height Unit Toggle (cm vs ft/in)
   ========================================================================== */
let currentHeightUnit = 'cm';

function initHeightUnitToggle() {
  const btnCm = document.getElementById('unitBtnCm');
  const btnFt = document.getElementById('unitBtnFt');
  const heightCmGroup = document.getElementById('heightCmGroup');
  const heightFtInGroup = document.getElementById('heightFtInGroup');
  const inputCm = document.getElementById('calcHeightCm');
  const inputFt = document.getElementById('calcHeightFt');
  const inputIn = document.getElementById('calcHeightIn');

  if (!btnCm || !btnFt) return;

  btnCm.addEventListener('click', () => {
    if (currentHeightUnit === 'cm') return;
    currentHeightUnit = 'cm';
    btnCm.classList.add('active');
    btnFt.classList.remove('active');
    heightCmGroup.style.display = 'block';
    heightFtInGroup.style.display = 'none';

    // Convert from ft/in to cm
    const ft = Number(inputFt.value) || 0;
    const inch = Number(inputIn.value) || 0;
    if (ft > 0) {
      inputCm.value = Math.round(((ft * 12) + inch) * 2.54);
    }
    triggerCalculation();
  });

  btnFt.addEventListener('click', () => {
    if (currentHeightUnit === 'ft') return;
    currentHeightUnit = 'ft';
    btnFt.classList.add('active');
    btnCm.classList.remove('active');
    heightCmGroup.style.display = 'none';
    heightFtInGroup.style.display = 'grid';

    // Convert from cm to ft/in
    const cm = Number(inputCm.value) || 0;
    if (cm > 0) {
      const totalInches = cm / 2.54;
      inputFt.value = Math.floor(totalInches / 12);
      inputIn.value = Math.round(totalInches % 12);
    }
    triggerCalculation();
  });
}

function getNormalizedHeightCm() {
  if (currentHeightUnit === 'cm') {
    return Number(document.getElementById('calcHeightCm').value);
  } else {
    const ft = Number(document.getElementById('calcHeightFt').value) || 0;
    const inch = Number(document.getElementById('calcHeightIn').value) || 0;
    return Math.round(((ft * 12) + inch) * 2.54 * 10) / 10;
  }
}

/* ==========================================================================
   Calculator Handler & Real-Time Assessment
   ========================================================================== */
function initCalculator() {
  const form = document.getElementById('nutritionCalcForm');
  if (!form) return;

  const inputs = form.querySelectorAll('input, select');
  inputs.forEach(input => {
    input.addEventListener('input', triggerCalculation);
    input.addEventListener('change', triggerCalculation);
  });

  // Run initial calculation with default preset values
  triggerCalculation();
}

function triggerCalculation() {
  const age = document.getElementById('calcAge').value;
  const weight = document.getElementById('calcWeight').value;
  const height = getNormalizedHeightCm();
  const sex = document.querySelector('input[name="calcSex"]:checked')?.value || 'male';
  const activity = document.getElementById('calcActivity').value;
  const goal = document.getElementById('calcGoal').value;

  // Clear previous inline errors
  clearFieldErrors();

  if (typeof assessNutrition !== 'function') {
    console.error('assessNutrition function not found in calculators.js');
    return;
  }

  const result = assessNutrition({ age, weight, height, sex, activity, goal });

  if (!result.success) {
    displayFieldErrors(result.errors);
    return;
  }

  renderResults(result);
}

function clearFieldErrors() {
  document.querySelectorAll('.field-error').forEach(el => {
    el.textContent = '';
    el.classList.remove('visible');
  });
}

function displayFieldErrors(errors) {
  if (errors.age) {
    showError('errorAge', errors.age);
  }
  if (errors.weight) {
    showError('errorWeight', errors.weight);
  }
  if (errors.height) {
    showError('errorHeight', errors.height);
  }
}

function showError(elemId, msg) {
  const el = document.getElementById(elemId);
  if (el) {
    el.textContent = msg;
    el.classList.add('visible');
  }
}

function renderResults(res) {
  const { isMinor, minorMessage, bmiData, bmr, tdee, goalCalories, floorApplied, floorMessage, macros } = res;

  // 1. BMI Card
  document.getElementById('resBmiValue').textContent = bmiData.bmi.toFixed(1);
  const bmiBadge = document.getElementById('resBmiBadge');
  bmiBadge.textContent = bmiData.category;
  bmiBadge.style.backgroundColor = `${bmiData.color}22`;
  bmiBadge.style.color = bmiData.color;
  bmiBadge.style.border = `1px solid ${bmiData.color}`;

  // 2. BMR & TDEE
  document.getElementById('resBmrValue').textContent = `${Math.round(bmr)} kcal`;
  document.getElementById('resTdeeValue').textContent = `${Math.round(tdee)} kcal`;

  const adultResultsWrap = document.getElementById('adultResultsContainer');
  const minorAdvisoryBox = document.getElementById('minorAdvisoryBox');

  // 3. Minor Handling (< 18)
  if (isMinor) {
    adultResultsWrap.style.display = 'none';
    minorAdvisoryBox.style.display = 'block';
    minorAdvisoryBox.textContent = minorMessage;
    return;
  }

  adultResultsWrap.style.display = 'block';
  minorAdvisoryBox.style.display = 'none';

  // 4. Goal Calories & Safety Floor
  document.getElementById('resGoalCalories').textContent = goalCalories.toLocaleString();
  const floorAlert = document.getElementById('safetyFloorAlert');
  if (floorApplied && floorMessage) {
    floorAlert.style.display = 'block';
    floorAlert.textContent = `⚠️ ${floorMessage}`;
  } else {
    floorAlert.style.display = 'none';
  }

  // 5. Macro Breakdown
  if (macros) {
    document.getElementById('barProtein').style.width = `${macros.protein.percentage}%`;
    document.getElementById('barCarbs').style.width = `${macros.carbs.percentage}%`;
    document.getElementById('barFats').style.width = `${macros.fats.percentage}%`;

    document.getElementById('valProteinGrams').textContent = `${macros.protein.grams}g`;
    document.getElementById('valProteinPct').textContent = `${macros.protein.kcal} kcal (${macros.protein.percentage}%)`;

    document.getElementById('valCarbsGrams').textContent = `${macros.carbs.grams}g`;
    document.getElementById('valCarbsPct').textContent = `${macros.carbs.kcal} kcal (${macros.carbs.percentage}%)`;

    document.getElementById('valFatsGrams').textContent = `${macros.fats.grams}g`;
    document.getElementById('valFatsPct').textContent = `${macros.fats.kcal} kcal (${macros.fats.percentage}%)`;
  }
}

/* ==========================================================================
   Prompt Chips (Copy-to-Clipboard)
   ========================================================================== */
function initPromptChips() {
  const chips = document.querySelectorAll('.prompt-chip');
  chips.forEach(chip => {
    chip.addEventListener('click', () => {
      const textToCopy = chip.getAttribute('data-prompt') || chip.innerText.trim();
      copyToClipboard(textToCopy, 'Prompt copied! Paste it into the Watsonx agent.');
    });
  });
}

/* ==========================================================================
   Sync Profile to Agent (Prepares & Copies Prompt)
   ========================================================================== */
function initCopyProfile() {
  const btn = document.getElementById('copyProfilePromptBtn');
  if (!btn) return;

  btn.addEventListener('click', () => {
    const age = document.getElementById('calcAge').value;
    const weight = document.getElementById('calcWeight').value;
    const height = getNormalizedHeightCm();
    const sex = document.querySelector('input[name="calcSex"]:checked')?.value || 'male';
    const activity = document.getElementById('calcActivity').options[document.getElementById('calcActivity').selectedIndex].text;
    const goal = document.getElementById('calcGoal').options[document.getElementById('calcGoal').selectedIndex].text;
    const diet = document.getElementById('calcDietPref').value;
    const location = document.getElementById('calcLocation').value.trim() || 'India';
    const conditions = document.getElementById('calcConditions').value.trim() || 'None';

    const goalCal = document.getElementById('resGoalCalories')?.textContent || 'Target';
    const bmi = document.getElementById('resBmiValue')?.textContent || '';

    const formattedPrompt = 
`Hello Nutrition Agent! Please provide me a personalized 1-day diet nutrition plan based on my profile:
- Age: ${age} years
- Biological Sex: ${sex.charAt(0).toUpperCase() + sex.slice(1)}
- Height: ${height} cm
- Weight: ${weight} kg (BMI: ${bmi})
- Primary Goal: ${goal} (Estimated Target: ${goalCal} kcal)
- Activity Level: ${activity}
- Dietary Preference: ${diet}
- Location: ${location}
- Medical Conditions / Allergies: ${conditions}

Please include:
1. User profile summary table
2. Meal-by-meal plan (Breakfast, Mid-morning snack, Lunch, Evening snack, Dinner) with 2-3 alternatives each
3. Explain why the key foods were selected for my goal and region.`;

    copyToClipboard(formattedPrompt, 'Profile Prompt copied! Paste it in the Watsonx Orchestrate chat.');
  });
}

/* ==========================================================================
   Clipboard Helper & Toast
   ========================================================================== */
function copyToClipboard(text, successMessage = 'Copied to clipboard!') {
  if (navigator.clipboard && window.isSecureContext) {
    navigator.clipboard.writeText(text).then(() => {
      showToast(successMessage);
    }).catch(() => {
      fallbackCopy(text, successMessage);
    });
  } else {
    fallbackCopy(text, successMessage);
  }
}

function fallbackCopy(text, successMessage) {
  const textArea = document.createElement('textarea');
  textArea.value = text;
  textArea.style.position = 'fixed';
  textArea.style.left = '-999999px';
  document.body.appendChild(textArea);
  textArea.focus();
  textArea.select();
  try {
    document.execCommand('copy');
    showToast(successMessage);
  } catch (err) {
    alert('Copy failed. Please manually copy the prompt.');
  }
  document.body.removeChild(textArea);
}

function showToast(message) {
  let toast = document.getElementById('toastNotice');
  if (!toast) {
    toast = document.createElement('div');
    toast.id = 'toastNotice';
    toast.className = 'toast-notice';
    document.body.appendChild(toast);
  }

  toast.innerHTML = `
    <svg fill="none" viewBox="0 0 24 24" stroke="currentColor">
      <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M5 13l4 4L19 7"/>
    </svg>
    <span>${message}</span>
  `;

  toast.classList.add('visible');
  setTimeout(() => {
    toast.classList.remove('visible');
  }, 3500);
}

/* ==========================================================================
   Watsonx Orchestrate Fallback Check
   ========================================================================== */
function initWebchatFallback() {
  // Check if Watsonx Orchestrate webchat script is loaded
  setTimeout(() => {
    const chatStatusText = document.getElementById('chatStatusNote');
    const hasWatsonx = window.wxOConfiguration || window.watsonAssistantChatOptions || document.querySelector('#WACContainer') || document.querySelector('script[src*="wxochat"]');
    if (chatStatusText) {
      if (hasWatsonx) {
        chatStatusText.textContent = '🟢 Watsonx Orchestrate Agent channel active. Open the floating launcher in the bottom corner to chat!';
        chatStatusText.style.color = 'var(--status-success)';
      } else {
        chatStatusText.textContent = 'ℹ️ Note: Orchestrate script snippet can be pasted into index.html <head> for live embedded widget.';
      }
    }
  }, 1500);
}
